 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal bands: repeat the fully specified rows to fill a trailing
    # run of empty (all-zero) bands.
    if all(len(set(row)) == 1 for row in grid):
        out = [row[:] for row in grid]
        end = h
        while end > 0 and all(v == 0 for v in out[end - 1]):
            end -= 1
        if 0 < end < h:
            period = end
            for r in range(end, h):
                out[r] = out[r % period][:]
        return out

    # Complete a cyclic diagonal sequence.  Each row is the same cycle,
    # shifted one place horizontally per row; infer shift orientation from
    # the nonzero cells already present.
    candidates = []
    if h == w:
        n = w
        for sign in (-1, 1):
            seq = [None] * n
            valid = True
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    if v == 0:
                        continue
                    k = (c + sign * r) % n
                    if seq[k] is not None and seq[k] != v:
                        valid = False
                        break
                    seq[k] = v
                if not valid:
                    break
            if valid and all(v is not None for v in seq):
                candidates.append([[seq[(c + sign * r) % n] for c in range(w)] for r in range(h)])
    if candidates:
        for out in candidates:
            if all(grid[r][c] == 0 or grid[r][c] == out[r][c]
                   for r in range(h) for c in range(w)):
                return out
    return [row[:] for row in grid]

